-- Fixture for the ClickHouse quickstart e2e job (.github/workflows/e2e_test_ci.yml),
-- which registers this table through the ClickHouse connector and runs SELECT *.
--
-- `date32_column` is a guard, not sample data: ClickHouse `Date32` decoding is a
-- Spice patch to the `spiceai/clickhouse-rs` fork (docs/dev/fork_patches.md), and
-- it can only be exercised against a real server — the wire type name is what
-- selects the 32-bit column, and nothing client-side can build one. Two of its
-- values are outside the 1970-01-01..2149-06-06 range a 16-bit `Date` can hold, so
-- losing the patch leaves the type unrecognised and fails the SELECT.
CREATE TABLE test_clickhouse_table (uuid_column UUID, bool_column Bool, int8_column Int8, int16_column Int16, int32_column Int32, int64_column Int64, uint8_column UInt8, uint16_column UInt16, uint32_column UInt32, uint64_column UInt64, float32_column Float32, float64_column Float64, string_column String, fixed_string_column FixedString(10), date_column Date, date32_column Date32, datetime_column DateTime, decimal_column Decimal(18, 4), nullable_string Nullable(String), nullable_datetime_column Nullable(Datetime)) ENGINE = MergeTree() ORDER BY uuid_column;
INSERT INTO test_clickhouse_table (uuid_column, bool_column, int8_column, int16_column, int32_column, int64_column, uint8_column, uint16_column, uint32_column, uint64_column, float32_column, float64_column, string_column, fixed_string_column, date_column, date32_column, datetime_column, decimal_column, nullable_string, nullable_datetime_column) VALUES ('01234567-89ab-cdef-0123-456789abcdef', 1, 10, 100, 1000, 10000, 20, 200, 2000, 20000, 1.23, 2.34, 'test_string_1', 'fixedstr10', '2024-04-24', '1900-01-01', '2024-04-24 12:34:56', 123.456, NULL, '2024-04-24 12:34:56'), ('01234567-89ab-cdef-1123-456789abcdef', 1, 11, 101, 1001, 10001, 21, 201, 2001, 20001, 1.24, 2.35, 'test_string_2', 'fixedstr_2', '2024-04-25', '2200-01-01', '2024-04-25 12:35:57', 124.457, 'nullable_2', '2024-04-25 12:35:57'), ('01234567-89ab-cdef-1223-456789abcdef', 1, 12, 102, 1002, 10002, 22, 202, 2002, 20002, 1.25, 2.36, 'test_string_3', 'fixedstr_3', '2024-04-26', '2024-04-26', '2024-04-26 12:36:58', 125.458, 'nullable_3', NULL);
